// Phase 6 — the citizen's device wallet.
// A NON-EXTRACTABLE P-256 key is generated by WebCrypto and kept in IndexedDB on this device: scripts can
// ask the browser to sign with it, but nobody (not even this page) can read the private key out.
// Every use is preceded by a passkey check that Mithaq verifies (a "ceremony").
import { startAuthentication } from '@simplewebauthn/browser';
import { api } from './api.ts';

interface StoredKey { subject: string; kid: string | null; privateKey: CryptoKey; publicJwk: JsonWebKey }

const DB = 'sarab-wallet';
function idb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const r = indexedDB.open(DB, 1);
    r.onupgradeneeded = () => r.result.createObjectStore('keys', { keyPath: 'subject' });
    r.onsuccess = () => resolve(r.result);
    r.onerror = () => reject(r.error);
  });
}
async function store<T>(mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  const db = await idb();
  return new Promise((resolve, reject) => {
    const req = fn(db.transaction('keys', mode).objectStore('keys'));
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export const getDeviceKey = (subject: string) => store<StoredKey | undefined>('readonly', (s) => s.get(subject));
export const forgetDeviceKey = (subject: string) => store('readwrite', (s) => s.delete(subject));

const b64u = (buf: ArrayBuffer | Uint8Array) => btoa(String.fromCharCode(...new Uint8Array(buf as ArrayBuffer))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const utf8 = (s: string) => new TextEncoder().encode(s);
const b64uText = (s: string) => b64u(utf8(s));

async function es256(key: CryptoKey, header: object, payload: string): Promise<string> {
  const input = `${b64uText(JSON.stringify(header))}.${b64uText(payload)}`;
  const sig = await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, utf8(input)); // raw r||s = JWS format
  return `${input}.${b64u(sig)}`;
}

/** Move the signing key to this device: passkey check, then generate + register the public key. */
export async function enrolDeviceKey(subject: string): Promise<string> {
  const { ceremony_id, options } = await api<{ ceremony_id: string; options: any }>('/api/identity/me/device-key/options', { body: {} });
  const assertion = await startAuthentication({ optionsJSON: options });
  const kp = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign', 'verify']);
  const { kty, crv, x, y } = await crypto.subtle.exportKey('jwk', kp.publicKey);
  const r = await api<{ kid: string }>('/api/identity/me/device-key', { body: { ceremony_id, assertion, public_jwk: { kty, crv, x, y } } });
  await store('readwrite', (s) => s.put({ subject, kid: r.kid, privateKey: kp.privateKey, publicJwk: { kty, crv, x, y } } satisfies StoredKey));
  return r.kid;
}

export class NoDeviceKeyHere extends Error {}

/** A device-signed action: Mithaq fixes the payload, the passkey confirms, the device signs. */
export async function ceremony<T = any>(subject: string, purpose: 'document' | 'mandate' | 'wallet', input: Record<string, unknown>): Promise<T> {
  const key = await getDeviceKey(subject);
  if (!key) throw new NoDeviceKeyHere('The signing key is on another device');
  const c = await api<{ ceremony_id: string; options: any; payload_json: string | null; kid: string }>('/api/identity/me/ceremonies', { body: { purpose, input } });
  const assertion = await startAuthentication({ optionsJSON: c.options });
  const jws = c.payload_json ? await es256(key.privateKey, { alg: 'ES256', kid: c.kid }, c.payload_json) : undefined;
  return api<T>(`/api/identity/me/ceremonies/${c.ceremony_id}/complete`, { body: { assertion, ...(jws ? { jws } : {}) } });
}

/** Holder side of SD-JWT: keep only the approved disclosures and add a key-binding JWT signed on the device. */
async function present(subject: string, sdJwt: string, reveal: string[], aud: string, nonce: string): Promise<string> {
  const key = await getDeviceKey(subject);
  if (!key) throw new NoDeviceKeyHere('The signing key is on another device');
  const [jwt, ...rest] = sdJwt.split('~');
  const name = (d: string) => JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(d.replace(/-/g, '+').replace(/_/g, '/')), (ch) => ch.charCodeAt(0))))[1];
  const kept = rest.filter(Boolean).filter((d) => reveal.includes(name(d)));
  const unbound = `${jwt}~${kept.map((d) => `${d}~`).join('')}`;
  const sdHash = b64u(await crypto.subtle.digest('SHA-256', utf8(unbound)));
  const kb = await es256(key.privateKey, { alg: 'ES256', typ: 'kb+jwt' }, JSON.stringify({ nonce, aud, iat: Math.floor(Date.now() / 1000), sd_hash: sdHash }));
  return unbound + kb;
}

/** After approving a consent: get device-bound credentials (passkey check) and hand Idhn the presentations. */
export async function shareFromDevice(subject: string, consentId: string, claims: string[], audience: string, nonce: string): Promise<void> {
  const w = await ceremony<{ credentials: { credential: string; vct: string; issuer: string; sd_jwt: string }[] }>(subject, 'wallet', { consent_id: consentId, claims });
  const presentations = [];
  for (const c of w.credentials) presentations.push({ credential: c.credential, vct: c.vct, issuer: c.issuer, presentation: await present(subject, c.sd_jwt, claims, audience, nonce) });
  await api(`/api/consent/consents/${encodeURIComponent(consentId)}/presentations`, { body: { presentations } });
}

export interface KeyStatus { mode: 'cloud' | 'device'; kid: string | null; server_holds_private_key: boolean; passkey: { nickname: string } | null; enrolled_at: string | null }
export const keyStatus = () => api<KeyStatus>('/api/identity/me/device-key');
